<script setup>
import MiddleEllipsis from './MiddleEllipsis.vue';
import { computed, nextTick, ref, useId, watch } from 'vue';
const props=defineProps({modelValue:{type:String,default:''},options:{type:Array,default:()=>[]},placeholder:{type:String,default:'搜索并选择'},label:String,allowCustom:Boolean});
const emit=defineEmits(['update:modelValue']);
const query=ref(''),open=ref(false),active=ref(-1);const id=useId();
watch(()=>props.modelValue,value=>{query.value=value||'';},{immediate:true});
const filtered=computed(()=>props.options.filter(v=>String(v).toLocaleLowerCase().includes((query.value===props.modelValue?'':query.value.trim()).toLocaleLowerCase())));
function choose(value){open.value=false;active.value=-1;emit('update:modelValue',value);nextTick(()=>{query.value=props.modelValue||'';});}
function input(){open.value=true;active.value=-1;}
function blur(){if(props.allowCustom&&query.value.trim()!==props.modelValue)choose(query.value.trim());else query.value=props.modelValue||'';open.value=false;}
function keydown(event){if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();open.value=true;const step=event.key==='ArrowDown'?1:-1;active.value=filtered.value.length?(active.value<0?(step>0?0:filtered.value.length-1):(active.value+step+filtered.value.length)%filtered.value.length):-1;}else if(event.key==='Enter'){event.preventDefault();if(open.value&&active.value>=0&&filtered.value[active.value]!==undefined)choose(filtered.value[active.value]);else if(props.allowCustom)choose(query.value.trim());else if(filtered.value.includes(query.value))choose(query.value);}else if(event.key==='Escape'){event.stopPropagation();open.value=false;query.value=props.modelValue||'';}}
</script>
<template><div class="search-select"><div class="search-select-input"><input :value="query" :placeholder="placeholder" :aria-label="label" role="combobox" aria-autocomplete="list" :aria-expanded="open" :aria-controls="id" :aria-activedescendant="open&&active>=0?id+'-'+active:undefined" @input="query=$event.target.value;input()" @focus="open=true" @blur="blur" @keydown="keydown" /><button v-if="modelValue" type="button" class="select-clear" :aria-label="'清空'+(label||'选择')" @pointerdown.prevent @click="choose('')">×</button><span v-else class="select-chevron" aria-hidden="true">⌄</span></div><div v-if="open" :id="id" class="search-select-options" role="listbox" :aria-label="label"><button v-for="(value,i) in filtered" :id="id+'-'+i" :key="value" type="button" role="option" :aria-selected="modelValue===value" :class="{active:i===active}" tabindex="-1" @pointerdown.prevent @click="choose(value)"><MiddleEllipsis :text="String(value)" :tail="6" /></button><div v-if="!filtered.length" class="select-empty">{{ allowCustom?'回车使用输入内容':'无匹配项，可在基础档案中新增' }}</div></div></div></template>
<style scoped>.search-select{position:relative;min-width:0;width:100%;font-size:12px}.search-select-input{position:relative}.search-select input{width:100%;height:38px;border:1px solid #d6dee8;border-radius:6px;padding:8px 30px 8px 10px!important;background:white;color:#263548;outline:none}.search-select input:focus{border-color:#4d8ac9;box-shadow:0 0 0 3px #1867c014}.select-clear,.select-chevron{position:absolute;right:7px;top:8px;color:#7d8da0;border:0;background:none;font-size:17px;line-height:20px}.select-clear{cursor:pointer}.search-select-options{position:absolute;top:calc(100% + 4px);left:0;right:0;z-index:100;max-height:210px;overflow:auto;padding:4px;border:1px solid #dbe4ee;border-radius:7px;background:white;box-shadow:0 8px 24px #26354818}.search-select-options button{display:block;width:100%;padding:9px;text-align:left;border:0;border-radius:4px;background:white;color:#36485d;font-size:12px;cursor:pointer}.search-select-options button:hover,.search-select-options button.active{background:#eaf3ff}.search-select-options button[aria-selected=true]{color:#1867c0}.select-empty{padding:10px;color:#8a98a9;font-size:11px}</style>
